"""Demo: Euler's totient counts the self-identifications of Z/nZ."""
from __future__ import annotations
from math import gcd
from typing import List


def euler_totient(n: int) -> int:
    """phi(n) = #{1 <= k <= n : gcd(k, n) = 1}."""
    return sum(1 for k in range(1, n + 1) if gcd(k, n) == 1)


def automorphism_count(n: int) -> int:
    """Number of additive automorphisms x -> k*x of Z/nZ (k a unit)."""
    units: List[int] = [k for k in range(1, n + 1) if gcd(k, n) == 1]
    return len(units)


if __name__ == "__main__":
    for n in range(1, 21):
        assert automorphism_count(n) == euler_totient(n)
        print(f"n={n:2d}: ambiguity = |Aut(Z/nZ)| = phi(n) = {euler_totient(n)}")

"""Demo: collisions and non-collisions of groups of equal order."""
from __future__ import annotations
from math import gcd, lcm
from typing import Dict, Tuple


def add_order(a: int, n: int) -> int:
    a %= n
    return 1 if a == 0 else n // gcd(a, n)


def spectrum_cyclic(n: int) -> Dict[int, int]:
    s: Dict[int, int] = {}
    for a in range(n):
        o = add_order(a, n)
        s[o] = s.get(o, 0) + 1
    return s


def spectrum_product(m: int, n: int) -> Dict[int, int]:
    s: Dict[int, int] = {}
    for a in range(m):
        for b in range(n):
            o = lcm(add_order(a, m), add_order(b, n))
            s[o] = s.get(o, 0) + 1
    return s


if __name__ == "__main__":
    # Collision: Z/6Z ~= Z/2Z x Z/3Z
    print("Z/6Z        :", spectrum_cyclic(6))
    print("Z/2Z x Z/3Z :", spectrum_product(2, 3))
    print("Collision (equal spectra):", spectrum_cyclic(6) == spectrum_product(2, 3))
    print()
    # Non-collision: Z/4Z  vs  Z/2Z x Z/2Z
    print("Z/4Z        :", spectrum_cyclic(4))
    print("Z/2Z x Z/2Z :", spectrum_product(2, 2))
    print("Non-collision (spectra differ):",
          spectrum_cyclic(4) != spectrum_product(2, 2))

